// *** SUPERSEDED (Phase 1 of the FIS Forms Library engine migration) ***
// This hand-written, per-form script is kept only as a historical
// reference for how 2014-13-006's customer-preview generation worked
// before the shared engine existed. It is no longer run by anything and
// is no longer the source of truth for 2014-13-006's behavior.
//
// The current, maintained implementation is:
//   bi-forms-library/engine/cli.js  (shared entry point for every form)
//   bi-forms-library/configs/2014-13-006/  (this form's coordinate-map.json,
//                                        questionnaire.json, sample-data.json)
// Regression coverage: bi-forms-library/tests/run-all.js
//
// Do not edit this file to fix a bug or add a feature -- make the change
// in bi-forms-library/engine/lib/ and this form's configs/ instead, and
// the tests cover it there. This file is left in place, unmodified below
// this notice, purely so the original approach remains inspectable.
// ---------------------------------------------------------------------

// Embeds the composited two-region canvas (customer-canvas.png) into a new
// single-page PDF, draws the PREVIEW ONLY watermark and a short divider
// caption as vector text on top of the raster, and applies the adopted
// metadata-minimization standard. The resulting file contains ONLY pixel
// data from the two approved regions plus this overlay text -- nothing
// from the excluded staff-only strip exists in the file at all.
const fs = require("fs");
const path = require("path");
const { PDFDocument, StandardFonts, rgb, degrees } = require("pdf-lib");

const DIR = __dirname;
const map = JSON.parse(fs.readFileSync(path.join(DIR, "coordinate-map.json"), "utf8"));
const dims = JSON.parse(fs.readFileSync(path.join(DIR, "canvas-dims.json"), "utf8"));

function addWatermark(page, text, font, bounds) {
  const angle = (28 * Math.PI) / 180;
  let size = 20;
  while (size > 8) {
    const w = font.widthOfTextAtSize(text, size);
    const footprintW = w * Math.cos(angle) + size * Math.sin(angle);
    const footprintH = w * Math.sin(angle) + size * Math.cos(angle);
    if (footprintW <= bounds.width * 0.92 && footprintH <= bounds.height * 0.92) break;
    size -= 0.5;
  }
  const textWidth = font.widthOfTextAtSize(text, size);
  const cx = bounds.xLeft + bounds.width / 2;
  const cy = bounds.yBottom + bounds.height / 2;
  const x = cx - (textWidth / 2) * Math.cos(angle);
  const y = cy - (textWidth / 2) * Math.sin(angle);
  page.drawText(text, {
    x, y, size, font,
    color: rgb(0.78, 0.1, 0.1),
    opacity: 0.12,
    rotate: degrees(28),
  });
}

async function main() {
  const pngBytes = fs.readFileSync(path.join(DIR, "customer-canvas.png"));
  const doc = await PDFDocument.create();
  const png = await doc.embedPng(pngBytes);
  const page = doc.addPage([dims.widthPt, dims.heightPt]);
  page.drawImage(png, { x: 0, y: 0, width: dims.widthPt, height: dims.heightPt });

  const font = await doc.embedFont(StandardFonts.Helvetica);
  const fontIt = await doc.embedFont(StandardFonts.HelveticaOblique);

  // Divider caption -- same copy as the approved "FIS prepares the rest"
  // notice, shortened to fit the divider gap. Drawn as vector text, not
  // baked into the raster.
  const regionAHeightPt = dims.regionHeightsPt[0];
  const dividerCenterY = dims.heightPt - regionAHeightPt - dims.dividerPt / 2;
  const caption = "FIS staff prepare the remaining sections of this form";
  const capSize = 9;
  const capWidth = fontIt.widthOfTextAtSize(caption, capSize);
  page.drawText(caption, {
    x: dims.widthPt / 2 - capWidth / 2,
    y: dividerCenterY - capSize / 2,
    size: capSize,
    font: fontIt,
    color: rgb(0.45, 0.45, 0.45),
  });

  const wmFont = await doc.embedFont(StandardFonts.HelveticaBold);
  addWatermark(page, "PREVIEW ONLY | FOR BI APPLICATION PREPARATION THROUGH FIS", wmFont, {
    xLeft: 0, yBottom: 0, width: dims.widthPt, height: dims.heightPt,
  });

  doc.setAuthor("Foreign Immigration Services");
  doc.setCreator("FIS Forms Library");
  doc.setTitle(map.formTitle);

  fs.writeFileSync(path.join(DIR, "customer-preview.pdf"), await doc.save());
  console.log("Generated customer-preview.pdf:", dims.widthPt, "x", dims.heightPt, "pt");
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
